-- The usage ledger and its monthly totals for a PostgreSQL copy of the InvoiceSystem sample (it has a Tenant table). Settings:
-- ApiAuth=true, TenantTable=Tenant, UsageTables=UsageEvent, NoTenantTables=FeatureOverride (and UsageRollup=UsageMonthly when the roll-up is played).
-- The same tables and rows as the SQL Server InvoiceSystem and InvoiceSystem_test databases.
CREATE TABLE IF NOT EXISTS "UsageEvent" (
    "UsageEventId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "TenantId" integer NOT NULL REFERENCES "Tenant" ("TenantId"),
    "Kind" varchar(40) NOT NULL,
    "Quantity" numeric(12,2) NOT NULL DEFAULT 1,
    "OccurredOn" timestamp NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS "UsageMonthly" (
    "UsageMonthlyId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "TenantId" integer NOT NULL REFERENCES "Tenant" ("TenantId"),
    "Kind" varchar(40) NOT NULL,
    "UsageMonth" date NOT NULL,
    "Quantity" numeric(12,2) NOT NULL CHECK ("Quantity" >= 0),
    CONSTRAINT "UQ_UsageMonthly" UNIQUE ("TenantId", "Kind", "UsageMonth")
);

INSERT INTO "UsageEvent" ("TenantId", "Kind", "Quantity", "OccurredOn")
SELECT v.t, v.k, v.q, v.o::timestamp FROM (VALUES
    (1, 'api_calls', 1200.00, '2026-09-30 12:00:00'), (1, 'api_calls', 800.00, '2026-10-12 12:00:00'), (1, 'storage_gb', 3.50, '2026-10-15 00:00:00'),
    (2, 'api_calls', 150.00, '2026-10-20 12:00:00'), (2, 'storage_gb', 0.40, '2026-10-21 00:00:00')) AS v (t, k, q, o)
WHERE NOT EXISTS (SELECT 1 FROM "UsageEvent");

INSERT INTO "UsageMonthly" ("TenantId", "Kind", "UsageMonth", "Quantity")
SELECT v.t, v.k, v.m::date, v.q FROM (VALUES
    (1, 'api_calls', '2026-09-01', 1200.00), (1, 'api_calls', '2026-10-01', 800.00), (1, 'storage_gb', '2026-10-01', 3.50),
    (2, 'api_calls', '2026-10-01', 150.00), (2, 'storage_gb', '2026-10-01', 0.40)) AS v (t, k, m, q)
WHERE NOT EXISTS (SELECT 1 FROM "UsageMonthly");
